FROM (SELECT t.*,
             CONCAT(ifnull(t.apply_by_nickname, \'\'), \'(\', ifnull(t.APPLY_BY, \'\'), \')\') as APPLY_USER_NAME,
             b.ORG_BU_ID,
             b.ORG_BU_CODE,
             b.ORG_BU_NAME,
             b.REQUIRE_FROM,
             b.PROJECT_NAME,
             b.TOTAL_AMOUNT_BY_TEN_KILO,
             b.INVEST_NO,
             b.NO_REPORT_MONTH_PLAN_REASON,
             b.NEED_PUBLIC,
             user.USER_ID                                                                 VENDOR_USER_ID,
             user.USERNAME                                                                VENDOR_USERNAME,
             user.NICKNAME                                                                VENDOR_FULL_NAME,
             d.USER_ID                                                                    TECH_USER_ID,
             d.USERNAME                                                                   TECH_USERNAME,
             d.FULL_NAME                                                                  TECH_FULL_NAME,
             CONCAT(ifnull(c.FULL_NAME, \'\'), IF(c.USERNAME IS NOT NULL, \'(\', NULL), ifnull(c.USERNAME, \'\'),
                    IF(c.USERNAME IS NOT NULL, \')\', NULL))                             AS RESPONSIBILITY_USER_NAME
      FROM scc_pr_requirement_head t
               INNER JOIN scc_npm_pr_require_head b ON t.REQUIREMENT_HEAD_ID = b.REQUIREMENT_HEAD_ID
               LEFT JOIN scc_npm_pr_require_group c ON t.REQUIREMENT_HEAD_ID = c.REQUIREMENT_HEAD_ID AND c.GROUP_TYPE = \'VENDOR\'
               LEFT JOIN meicloud_usrm_cloud_rbac.scc_rbac_user user ON c.USER_ID = user.USER_ID
               LEFT JOIN scc_npm_pr_require_group d ON t.REQUIREMENT_HEAD_ID = d.REQUIREMENT_HEAD_ID AND d.GROUP_TYPE = \'SOU\'
      WHERE b.PREFIX_TECH_DISCUSSION = \'Y\'
      ORDER BY t.CREATION_DATE DESC) t
